cat >> test/app.test.ts <<'EOF'

const placeOrder = (token: string, body: unknown) =>
  fetch(`${base}/orders`, { method: "POST", headers: { ...as(token), "content-type": "application/json" }, body: JSON.stringify(body) });

const stockOf = async (id: number) => (await pool.query("select stock from products where id = $1", [id])).rows[0].stock;

test("POST /orders charges the total, reduces stock and returns the paid order", async () => {
  const before = { tshirt: await stockOf(1), mug: await stockOf(2) };
  const res = await placeOrder("bob-token", { items: [{ productId: 1, quantity: 2 }, { productId: 2, quantity: 1 }, { productId: 1, quantity: 1 }] });
  assert.equal(res.status, 201);
  const order = await res.json();
  assert.equal(order.status, "paid");
  assert.equal(order.total_cents, 3 * 2000 + 1200);
  assert.deepEqual(order.items, [
    { product_id: 1, quantity: 3, price_cents: 2000 },
    { product_id: 2, quantity: 1, price_cents: 1200 },
  ]);
  assert.equal(await stockOf(1), before.tshirt - 3);
  assert.equal(await stockOf(2), before.mug - 1);
  const { rows } = await pool.query("select payment_id, amount_cents from payment_calls where idempotency_key = $1", [`order-${order.id}`]);
  assert.deepEqual(rows, [{ payment_id: order.payment_id, amount_cents: 7200 }]);
  const mine = await (await fetch(`${base}/orders`, { headers: as("bob-token") })).json();
  assert.ok(mine.some((o: { id: number }) => o.id === order.id));
  const alices = await (await fetch(`${base}/orders`, { headers: as("alice-token") })).json();
  assert.ok(!alices.some((o: { id: number }) => o.id === order.id));
});

test("POST /orders rejects bad input with 400 and changes nothing", async () => {
  const charges = (await pool.query("select count(*)::int as n from payment_calls")).rows[0].n;
  for (const body of [
    {},
    { items: [] },
    { items: "x" },
    { items: [null] },
    { items: [{ productId: "1", quantity: 1 }] },
    { items: [{ productId: 1, quantity: 0 }] },
    { items: [{ productId: 1, quantity: -3 }] },
    { items: [{ productId: 1, quantity: 1.5 }] },
    { items: [{ productId: 0, quantity: 1 }] },
  ]) {
    const res = await placeOrder("alice-token", body);
    assert.equal(res.status, 400, JSON.stringify(body));
    assert.equal((await res.json()).error.code, "invalid_body");
  }
  const malformed = await fetch(`${base}/orders`, { method: "POST", headers: { ...as("alice-token"), "content-type": "application/json" }, body: "{" });
  assert.equal(malformed.status, 400);
  assert.equal((await pool.query("select count(*)::int as n from payment_calls")).rows[0].n, charges);
});

test("POST /orders: unknown product is 404, too little stock is 409, nothing charged or reserved", async () => {
  const stock = await stockOf(3);
  const missing = await placeOrder("alice-token", { items: [{ productId: 3, quantity: 1 }, { productId: 999, quantity: 1 }] });
  assert.equal(missing.status, 404);
  assert.equal((await missing.json()).error.code, "product_not_found");
  const tooMany = await placeOrder("alice-token", { items: [{ productId: 3, quantity: stock + 1 }] });
  assert.equal(tooMany.status, 409);
  assert.equal((await tooMany.json()).error.code, "insufficient_stock");
  assert.equal(await stockOf(3), stock);
});

test("POST /orders requires a token", async () => {
  const res = await placeOrder("nope", { items: [{ productId: 1, quantity: 1 }] });
  assert.equal(res.status, 401);
});

test("POST /orders in parallel never oversells, and charges exactly the orders that succeeded", async () => {
  const stock = await stockOf(3);
  const results = await Promise.all(
    Array.from({ length: 20 }, (_, i) =>
      placeOrder(i % 2 ? "alice-token" : "bob-token", { items: [{ productId: 2, quantity: 1 }, { productId: 3, quantity: 1 }] }),
    ),
  );
  const statuses = results.map((r) => r.status);
  assert.ok(statuses.every((s) => s === 201 || s === 409), statuses.join(","));
  const ok = await Promise.all(results.filter((r) => r.status === 201).map((r) => r.json()));
  assert.equal(ok.length, stock);
  assert.equal(await stockOf(3), 0);
  const { rows } = await pool.query(
    "select count(*)::int as n from payment_calls where idempotency_key = any($1)",
    [ok.map((o: { id: number }) => `order-${o.id}`)],
  );
  assert.equal(rows[0].n, stock);
  const pending = await pool.query("select count(*)::int as n from orders where status = 'pending'");
  assert.equal(pending.rows[0].n, 0);
});

test("POST /orders puts the stock back and marks the order failed when the charge fails", async () => {
  const stock = await stockOf(1);
  const original = payments.charge;
  payments.charge = async () => { throw new Error("card declined"); };
  try {
    const res = await placeOrder("alice-token", { items: [{ productId: 1, quantity: 2 }] });
    assert.equal(res.status, 502);
    assert.equal((await res.json()).error.code, "payment_failed");
  } finally {
    payments.charge = original;
  }
  assert.equal(await stockOf(1), stock);
  const { rows } = await pool.query("select status from orders order by id desc limit 1");
  assert.equal(rows[0].status, "failed");
});
EOF
